-- Truth or dare: replaces the spicy deck with a rewritten one.
-- Suggestive and intimate, not explicit. Encoded on purpose, so running
-- this shows no card. Please don't decode it.
-- Turns already played keep their own text; only the unplayed deck changes.

delete from public.td_cards where deck = 'spicy';

insert into public.td_cards (deck, kind, body, in_person_only)
select c ->> 'deck', c ->> 'kind', c ->> 'body', (c ->> 'in_person_only')::boolean
from jsonb_array_elements(convert_from(decode('', 'base64'), 'UTF8')::jsonb) as c
on conflict (body) do nothing;

-- Counts only.
select deck,
       count(*) filter (where kind = 'truth') as truths,
       count(*) filter (where kind = 'dare') as dares,
       count(*) filter (where in_person_only) as in_person_dares
from public.td_cards
group by deck
order by array_position(array['serious', 'funny', 'flirty', 'spicy'], deck);

notify pgrst, 'reload schema';
